    .axi_r_ready          (ddrMaster_4_axi_r_ready              ), //o
    .axi_r_payload_data   (ddr_r_payload_data[63:0]             ), //i
    .axi_r_payload_id     (ddr_r_payload_id[3:0]                ), //i
    .axi_r_payload_resp   (ddr_r_payload_resp[1:0]              ), //i
    .axi_r_payload_last   (ddr_r_payload_last                   ), //i
    .clk                  (clk                                  ), //i
    .reset                (reset                                )  //i
  );
  `ifndef SYNTHESIS
  always @(*) begin
    case(state)
      DescFetchState_IDLE : state_string = "IDLE   ";
      DescFetchState_START : state_string = "START  ";
      DescFetchState_COLLECT : state_string = "COLLECT";
      DescFetchState_DONE : state_string = "DONE   ";
      default : state_string = "???????";
    endcase
  end
  `endif

  assign ddr_aw_valid = ddrMaster_4_axi_aw_valid;
  assign ddr_aw_payload_addr = ddrMaster_4_axi_aw_payload_addr;
  assign ddr_aw_payload_id = ddrMaster_4_axi_aw_payload_id;
  assign ddr_aw_payload_len = ddrMaster_4_axi_aw_payload_len;
  assign ddr_aw_payload_size = ddrMaster_4_axi_aw_payload_size;
