  assign ddr_aw_payload_cache = ddrMaster_4_axi_aw_payload_cache;
  assign ddr_aw_payload_prot = ddrMaster_4_axi_aw_payload_prot;
  assign ddr_w_valid = ddrMaster_4_axi_w_valid;
  assign ddr_w_payload_data = ddrMaster_4_axi_w_payload_data;
  assign ddr_w_payload_strb = ddrMaster_4_axi_w_payload_strb;
  assign ddr_w_payload_last = ddrMaster_4_axi_w_payload_last;
  assign ddr_b_ready = ddrMaster_4_axi_b_ready;
  assign ddr_ar_valid = ddrMaster_4_axi_ar_valid;
  assign ddr_ar_payload_addr = ddrMaster_4_axi_ar_payload_addr;
  assign ddr_ar_payload_id = ddrMaster_4_axi_ar_payload_id;
  assign ddr_ar_payload_len = ddrMaster_4_axi_ar_payload_len;
  assign ddr_ar_payload_size = ddrMaster_4_axi_ar_payload_size;
  assign ddr_ar_payload_burst = ddrMaster_4_axi_ar_payload_burst;
  assign ddr_ar_payload_cache = ddrMaster_4_axi_ar_payload_cache;
  assign ddr_ar_payload_prot = ddrMaster_4_axi_ar_payload_prot;
  assign ddr_r_ready = ddrMaster_4_axi_r_ready;
  always @(*) begin
    ddrMaster_4_start = 1'b0;
    case(state)
      DescFetchState_IDLE : begin
      end
      DescFetchState_START : begin
        ddrMaster_4_start = 1'b1;
      end
      DescFetchState_COLLECT : begin
      end
      default : begin
      end
    endcase
  end

  always @(*) begin
    ddrMaster_4_rd_ready = 1'b0;
    case(state)
      DescFetchState_IDLE : begin
      end
      DescFetchState_START : begin
      end
      DescFetchState_COLLECT : begin
        ddrMaster_4_rd_ready = 1'b1;
      end
      default : begin
      end
    endcase
  end

  assign when_DescFetch_l152 = (go && (! ddrMaster_4_busy));
  assign when_DescFetch_l176 = (beatIdx == 2'b00);
  assign when_DescFetch_l176_1 = (beatIdx == 2'b01);
  assign when_DescFetch_l176_2 = (beatIdx == 2'b10);
  assign when_DescFetch_l176_3 = (beatIdx == 2'b11);
  assign when_DescFetch_l181 = (beatIdx == 2'b11);
  assign words_0 = wReg_0;
  assign words_1 = wReg_1;
  assign words_2 = wReg_2;
  assign words_3 = wReg_3;
  assign words_4 = wReg_4;
  assign words_5 = wReg_5;
  assign words_6 = wReg_6;
  assign words_7 = wReg_7;
  assign tpe = wReg_0[7 : 0];
  assign flags = wReg_0[15 : 8];
  assign imgW = wReg_1[15 : 0];
  assign imgH = wReg_1[31 : 16];
  assign cIn = wReg_2[15 : 0];
  assign cOut = wReg_2[31 : 16];
  assign group_1 = wReg_3[7 : 0];
  assign stride = wReg_3[11 : 8];
  assign pad = wReg_3[15 : 12];
  assign srcA = wReg_4;
  assign dstA = wReg_5;
  assign inBytes = wReg_6;
  assign qShift = wReg_7[7 : 0];
  assign layerId = wReg_7[15 : 8];
  assign isSentinel = (wReg_0[7 : 0] == 8'hff);
  assign head = (_zz_head[0] == 1'b0);
  assign tail = _zz_tail[1];
  assign words_valid = validR;
  assign busy = (busyR || ddrMaster_4_busy);
  assign err = ddrMaster_4_err;
  always @(posedge clk) begin
    if(reset) begin
      state <= DescFetchState_IDLE;
      beatIdx <= 2'b00;
      wReg_0 <= 32'h0;
      wReg_1 <= 32'h0;
      wReg_2 <= 32'h0;
      wReg_3 <= 32'h0;
      wReg_4 <= 32'h0;
      wReg_5 <= 32'h0;
      wReg_6 <= 32'h0;
      wReg_7 <= 32'h0;
      busyR <= 1'b0;
      validR <= 1'b0;
    end else begin
      case(state)
        DescFetchState_IDLE : begin
          if(when_DescFetch_l152) begin
            state <= DescFetchState_START;
            busyR <= 1'b1;
            validR <= 1'b0;
            beatIdx <= 2'b00;
          end
        end
        DescFetchState_START : begin
          state <= DescFetchState_COLLECT;
        end
        DescFetchState_COLLECT : begin
          if(ddrMaster_4_err) begin
            state <= DescFetchState_IDLE;
            busyR <= 1'b0;
          end
          if(ddrMaster_4_rd_valid) begin
            if(when_DescFetch_l176) begin
              wReg_0 <= ddrMaster_4_rd_data[31 : 0];
              wReg_1 <= ddrMaster_4_rd_data[63 : 32];
            end
            if(when_DescFetch_l176_1) begin
              wReg_2 <= ddrMaster_4_rd_data[31 : 0];
              wReg_3 <= ddrMaster_4_rd_data[63 : 32];
            end
            if(when_DescFetch_l176_2) begin
              wReg_4 <= ddrMaster_4_rd_data[31 : 0];
              wReg_5 <= ddrMaster_4_rd_data[63 : 32];
            end
            if(when_DescFetch_l176_3) begin
              wReg_6 <= ddrMaster_4_rd_data[31 : 0];
              wReg_7 <= ddrMaster_4_rd_data[63 : 32];
            end
            if(when_DescFetch_l181) begin
              state <= DescFetchState_DONE;
            end else begin
              beatIdx <= (beatIdx + 2'b01);
            end
          end
        end
        default : begin
          validR <= 1'b1;
          busyR <= 1'b0;
          state <= DescFetchState_IDLE;
        end
      endcase
    end
  end


endmodule

